package Q1;
import javax.swing.*;import java.awt.*;import java.sql.*;
class FeeService{private final String url,user,pwd;FeeService(String u,String n,String p){url=u;user=n;pwd=p;}void pay(String reg,double amount)throws Exception{if(reg==null||reg.isBlank()||!Double.isFinite(amount)||amount<=0)throw new IllegalArgumentException("Enter valid registration and positive amount");try(Connection c=DriverManager.getConnection(url,user,pwd);PreparedStatement s=c.prepareStatement("INSERT INTO fees(reg_no,amount) VALUES(?,?)")){s.setString(1,reg.trim());s.setDouble(2,amount);s.executeUpdate();}}}
public class FeeWindow extends JFrame{private final JTextField reg=new JTextField(12),amount=new JTextField(10);private final FeeService service=new FeeService(System.getenv().getOrDefault("DB_URL","jdbc:mysql://localhost:3306/campus_events"),System.getenv().getOrDefault("DB_USER","root"),System.getenv().getOrDefault("DB_PASSWORD",""));public FeeWindow(){super("Student Fee Payment");setLayout(new FlowLayout());add(new JLabel("Reg No"));add(reg);add(new JLabel("Amount"));add(amount);JButton pay=new JButton("Pay"),clear=new JButton("Clear"),receipt=new JButton("Receipt");add(pay);add(clear);add(receipt);pay.addActionListener(e->{try{double a=Double.parseDouble(amount.getText().trim());new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{service.pay(reg.getText(),a);return null;}protected void done(){try{get();JOptionPane.showMessageDialog(FeeWindow.this,"Payment successful");}catch(Exception ex){JOptionPane.showMessageDialog(FeeWindow.this,"Payment failed: "+ex.getMessage());}}}.execute();}catch(NumberFormatException ex){JOptionPane.showMessageDialog(this,"Enter a valid amount");}});clear.addActionListener(e->{reg.setText("");amount.setText("");});receipt.addActionListener(e->JOptionPane.showMessageDialog(this,"Receipt lookup should use the payment ID."));setDefaultCloseOperation(EXIT_ON_CLOSE);pack();}public static void main(String[]x){SwingUtilities.invokeLater(()->new FeeWindow().setVisible(true));}}
